package com.atlasgrid.geoops.tools.preflight;

/**
 * Result returned by the standalone GIS dataset preflight validator.
 *
 * @param valid    whether the input passed validation
 * @param exitCode operating-system process exit code
 * @param message  human-readable result
 */
public record PreflightResult(
        boolean valid,
        int exitCode,
        String message
) {
    public static PreflightResult success(String message) {
        return new PreflightResult(true, 0, message);
    }

    public static PreflightResult failure(int exitCode, String message) {
        return new PreflightResult(false, exitCode, message);
    }
}

package com.atlasgrid.geoops.tools.preflight;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Locale;
import java.util.Set;

/**
 * Lightweight command-line preflight validation for inbound GIS data files.
 *
 * <p>This validator deliberately contains no System.exit call. Business logic
 * returns a result; only the outer CLI boundary decides whether the JVM process
 * should terminate with a non-zero status.</p>
 */
public class DatasetPreflightValidator {

    private static final Set<String> SUPPORTED_EXTENSIONS =
            Set.of(".csv", ".json", ".geojson");

    public PreflightResult validate(String[] args) {
        if (args == null || args.length != 1 || args[0].isBlank()) {
            return PreflightResult.failure(
                    2,
                    "Usage: GeoOpsPreflightCli <dataset-file>"
            );
        }

        Path dataset = Path.of(args[0]);

        if (!Files.exists(dataset)) {
            return PreflightResult.failure(
                    3,
                    "Dataset does not exist: " + dataset
            );
        }

        if (!Files.isRegularFile(dataset)) {
            return PreflightResult.failure(
                    4,
                    "Dataset path is not a regular file: " + dataset
            );
        }

        String fileName = dataset.getFileName().toString().toLowerCase(Locale.ROOT);
        boolean supported = SUPPORTED_EXTENSIONS.stream().anyMatch(fileName::endsWith);

        if (!supported) {
            return PreflightResult.failure(
                    5,
                    "Unsupported dataset type. Supported: " + SUPPORTED_EXTENSIONS
            );
        }

        return PreflightResult.success(
                "Dataset passed basic GeoOps preflight checks: " + dataset
        );
    }
}

package com.atlasgrid.geoops.tools.preflight;

/**
 * Standalone process used by batch/Jenkins-style workflows before an inbound
 * GIS dataset is submitted to GeoOps.
 *
 * <p>System.exit is intentionally restricted to this outer application
 * boundary. Controllers, services and domain logic must not terminate the JVM.</p>
 */
public final class GeoOpsPreflightCli {

    private GeoOpsPreflightCli() {
    }

    public static void main(String[] args) {
        DatasetPreflightValidator validator = new DatasetPreflightValidator();
        PreflightResult result = validator.validate(args);

        if (result.valid()) {
            System.out.println(result.message());
            return;
        }

        System.err.println(result.message());
        System.exit(result.exitCode());
    }
}

package com.atlasgrid.geoops.tools.preflight;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

import static org.assertj.core.api.Assertions.assertThat;

class DatasetPreflightValidatorTest {

    private final DatasetPreflightValidator validator = new DatasetPreflightValidator();

    @TempDir
    Path tempDir;

    @Test
    void returnsUsageErrorWhenNoDatasetWasProvided() {
        PreflightResult result = validator.validate(new String[0]);

        assertThat(result.valid()).isFalse();
        assertThat(result.exitCode()).isEqualTo(2);
    }

    @Test
    void returnsNotFoundWhenDatasetDoesNotExist() {
        PreflightResult result =
                validator.validate(new String[]{tempDir.resolve("missing.geojson").toString()});

        assertThat(result.valid()).isFalse();
        assertThat(result.exitCode()).isEqualTo(3);
    }

    @Test
    void rejectsUnsupportedDatasetType() throws IOException {
        Path dataset = Files.createFile(tempDir.resolve("survey.exe"));

        PreflightResult result = validator.validate(new String[]{dataset.toString()});

        assertThat(result.valid()).isFalse();
        assertThat(result.exitCode()).isEqualTo(5);
    }

    @Test
    void acceptsSupportedGeoJsonDataset() throws IOException {
        Path dataset = Files.createFile(tempDir.resolve("survey.geojson"));

        PreflightResult result = validator.validate(new String[]{dataset.toString()});

        assertThat(result.valid()).isTrue();
        assertThat(result.exitCode()).isZero();
    }
}
